rawInput.command:
set -e
REPO="$PWD"; T=$(mktemp -d)
CHROME="/Applications/Google Chrome.app/Contents/MacOS/Google Chrome"

# 1) Behaviour test: drive the real UI, report results in a <pre id=result>
python3 - "$REPO/index.html" "$T/test.html" <<'PY' 2>/dev/null || perl -0pe 's#</body>#<script>TEST</script></body>#' "$REPO/index.html" > "$T/test.html"
PY
TEST='localStorage.clear();state.todos=[];render();
const add=t=>{titleInput.value=t;form.requestSubmit();};
add("a");add("b");add("c");add("   ");
const r={};r.added=state.todos.length;
list.querySelector("li input").click();r.done=state.todos.filter(t=>t.done).length;
r.left=count.textContent;
document.querySelector("[data-filter=active]").click();r.active=list.children.length;
document.querySelector("[data-filter=completed]").click();r.completed=list.children.length;
document.querySelector("[data-filter=all]").click();
list.querySelectorAll(".delete")[2].click();r.afterDelete=state.todos.map(t=>t.title).join(",");
r.stored=JSON.parse(localStorage.getItem("todos")).length;
clear.click();r.afterClear=state.todos.map(t=>t.title).join(",");
document.body.insertAdjacentHTML("beforeend","<pre id=result>"+JSON.stringify(r)+"</pre>");'
perl -0pe 'BEGIN{$t=shift} s#</body>#<script>$t</script></body>#' "$TEST" "$REPO/index.html" > "$T/test.html"
"$CHROME" --headless=new --disable-gpu --user-data-dir="$T/p1" --dump-dom "file://$T/test.html" 2>/dev/null | grep -o '<pre id="result">.*</pre>'

# 2) Screenshot with seeded todos (seed runs before the app's script reads storage)
SEED='localStorage.setItem("todos",JSON.stringify([
{id:"1",title:"Buy oat milk and coffee beans",done:false},
{id:"2",title:"Review the quarterly roadmap",done:true},
{id:"3",title:"Book dentist appointment",done:false},
{id:"4",title:"Reply to Sam about the offsite",done:true},
{id:"5",title:"Water the plants",done:false}]));'
perl -0pe 'BEGIN{$t=shift} s#<script>#<script>$t</script>\n  <script>#' "$SEED" "$REPO/index.html" > "$T/seeded.html"
"$CHROME" --headless=new --disable-gpu --hide-scrollbars --user-data-dir="$T/p2" --window-size=1200,800 --screenshot="$REPO/screenshot.png" "file://$T/seeded.html" 2>&1 | tail -1
file "$REPO/screenshot.png"; rm -rf "$T"

