```console
diff --git a/index.html b/index.html
new file mode 100644
index 0000000..4073075
--- /dev/null
+++ b/index.html
@@ -0,0 +1,294 @@
+<!DOCTYPE html>
+<html lang="en">
+<head>
+  <meta charset="utf-8">
+  <meta name="viewport" content="width=device-width, initial-scale=1">
+  <title>Todos</title>
+  <style>
+    :root {
+      --bg: #f5f5f4;
+      --card: #ffffff;
+      --text: #1c1917;
+      --muted: #78716c;
+      --border: #e7e5e4;
+      --accent: #2563eb;
+      --danger: #dc2626;
+    }
+    * { box-sizing: border-box; }
+    body {
+      margin: 0;
+      min-height: 100vh;
+      background: var(--bg);
+      color: var(--text);
+      font: 16px/1.5 system-ui, -apple-system, "Segoe UI", sans-serif;
+      display: flex;
+      justify-content: center;
+      padding: 64px 16px;
+    }
+    main {
+      width: 100%;
+      max-width: 520px;
+    }
+    h1 {
+      margin: 0 0 24px;
+      font-size: 28px;
+      font-weight: 650;
+      letter-spacing: -0.02em;
+    }
+    .card {
+      background: var(--card);
+      border: 1px solid var(--border);
+      border-radius: 12px;
+      overflow: hidden;
+    }
+    form {
+      display: flex;
+      gap: 8px;
+      padding: 12px;
+      border-bottom: 1px solid var(--border);
+    }
+    input[type="text"] {
+      flex: 1;
+      padding: 10px 12px;
+      font: inherit;
+      border: 1px solid var(--border);
+      border-radius: 8px;
+      outline: none;
+    }
+    input[type="text"]:focus { border-color: var(--accent); }
+    button {
+      font: inherit;
+      cursor: pointer;
+      border: none;
+      background: none;
+      color: inherit;
+    }
+    .add {
+      padding: 10px 16px;
+      border-radius: 8px;
+      background: var(--accent);
+      color: #fff;
+      font-weight: 550;
+    }
+    ul {
+      list-style: none;
+      margin: 0;
+      padding: 0;
+    }
+    li {
+      display: flex;
+      align-items: center;
+      gap: 12px;
+      padding: 12px 16px;
+      border-bottom: 1px solid var(--border);
+    }
+    li input[type="checkbox"] {
+      width: 18px;
+      height: 18px;
+      accent-color: var(--accent);
+      cursor: pointer;
+    }
+    li span {
+      flex: 1;
+      word-break: break-word;
+    }
+    li.done span {
+      color: var(--muted);
+      text-decoration: line-through;
+    }
+    .delete {
+      color: var(--muted);
+      font-size: 20px;
+      line-height: 1;
+      padding: 2px 6px;
+      border-radius: 6px;
+      opacity: 0;
+    }
+    li:hover .delete, .delete:focus-visible { opacity: 1; }
+    .delete:hover { color: var(--danger); background: #fef2f2; }
+    .empty {
+      padding: 32px 16px;
+      text-align: center;
+      color: var(--muted);
+    }
+    footer {
+      display: flex;
+      align-items: center;
+      justify-content: space-between;
+      gap: 8px;
+      padding: 10px 16px;
+      font-size: 14px;
+      color: var(--muted);
+    }
+    .filters { display: flex; gap: 4px; }
+    .filters button, .clear {
+      padding: 4px 10px;
+      border-radius: 6px;
+    }
+    .filters button:hover, .clear:hover { background: var(--bg); }
+    .filters button[aria-pressed="true"] {
+      background: #eff6ff;
+      color: var(--accent);
+      font-weight: 550;
+    }
+    .clear[hidden] { display: none; }
+  </style>
+</head>
+<body>
+  <main>
+    <h1>Todos</h1>
+    <div class="card">
+      <form id="new-todo">
+        <input type="text" id="title" placeholder="What needs doing?" autocomplete="off" autofocus>
+        <button type="submit" class="add">Add</button>
+      </form>
+      <ul id="list"></ul>
+      <p class="empty" id="empty" hidden></p>
+      <footer>
+        <span id="count"></span>
+        <div class="filters" role="group" aria-label="Filter todos">
+          <button type="button" data-filter="all">All</button>
+          <button type="button" data-filter="active">Active</button>
+          <button type="button" data-filter="completed">Completed</button>
+        </div>
+        <button type="button" class="clear" id="clear">Clear completed</button>
+      </footer>
+    </div>
+  </main>
+
+  <script>
+    const STORAGE_KEY = "todos";
+
+    const state = {
+      todos: load(),
+      filter: "all",
+    };
+
+    const form = document.getElementById("new-todo");
+    const titleInput = document.getElementById("title");
+    const list = document.getElementById("list");
+    const empty = document.getElementById("empty");
