+  </main>
+
+  <script>
+    const STORAGE_KEY = "todos";
+
+    const state = {
+      todos: load(),
+      filter: "all",
+    };
+
+    const form = document.getElementById("new-todo");
+    const titleInput = document.getElementById("title");
+    const list = document.getElementById("list");
+    const empty = document.getElementById("empty");
+    const count = document.getElementById("count");
+    const clear = document.getElementById("clear");
+    const filterButtons = document.querySelectorAll("[data-filter]");
+
+    function load() {
+      try {
+        const saved = JSON.parse(localStorage.getItem(STORAGE_KEY));
+        return Array.isArray(saved) ? saved : [];
+      } catch {
+        return [];
+      }
+    }
+
+    function save() {
+      localStorage.setItem(STORAGE_KEY, JSON.stringify(state.todos));
+    }
+
+    function visibleTodos() {
+      if (state.filter === "active") return state.todos.filter((t) => !t.done);
+      if (state.filter === "completed") return state.todos.filter((t) => t.done);
+      return state.todos;
+    }
+
+    function render() {
+      list.replaceChildren(
+        ...visibleTodos().map((todo) => {
+          const li = document.createElement("li");
+          li.dataset.id = todo.id;
+          li.classList.toggle("done", todo.done);
+
+          const checkbox = document.createElement("input");
+          checkbox.type = "checkbox";
+          checkbox.checked = todo.done;
+          checkbox.setAttribute("aria-label", "Complete " + todo.title);
+
+          const title = document.createElement("span");
+          title.textContent = todo.title;
+
+          const remove = document.createElement("button");
+          remove.type = "button";
+          remove.className = "delete";
+          remove.textContent = "×";
+          remove.setAttribute("aria-label", "Delete " + todo.title);
+
+          li.append(checkbox, title, remove);
+          return li;
+        })
+      );
+
+      const remaining = state.todos.filter((t) => !t.done).length;
+      count.textContent = remaining + (remaining === 1 ? " item left" : " items left");
+
+      const emptyMessages = {
+        all: "Nothing to do yet. Add your first todo above.",
+        active: "No active todos.",
+        completed: "No completed todos.",
+      };
+      empty.hidden = list.children.length > 0;
+      empty.textContent = emptyMessages[state.filter];
+
+      clear.hidden = !state.todos.some((t) => t.done);
+
+      filterButtons.forEach((button) => {
+        button.setAttribute("aria-pressed", button.dataset.filter === state.filter);
+      });
+    }
+
+    function update(changes) {
+      changes();
+      save();
+      render();
+    }
+
+    form.addEventListener("submit", (event) => {
+      event.preventDefault();
+      const title = titleInput.value.trim();
+      if (!title) return;
+      update(() => {
+        state.todos.push({ id: crypto.randomUUID(), title, done: false });
+      });
+      titleInput.value = "";
+    });
+
+    list.addEventListener("change", (event) => {
+      if (event.target.type !== "checkbox") return;
+      const id = event.target.closest("li").dataset.id;
+      update(() => {
+        const todo = state.todos.find((t) => t.id === id);
+        todo.done = event.target.checked;
+      });
+    });
+
+    list.addEventListener("click", (event) => {
+      if (!event.target.classList.contains("delete")) return;
+      const id = event.target.closest("li").dataset.id;
+      update(() => {
+        state.todos = state.todos.filter((t) => t.id !== id);
+      });
+    });
+
+    filterButtons.forEach((button) => {
+      button.addEventListener("click", () => {
+        state.filter = button.dataset.filter;
+        render();
+      });
+    });
+
+    clear.addEventListener("click", () => {
+      update(() => {
+        state.todos = state.todos.filter((t) => !t.done);
+      });
+    });
+
+    // Keep multiple open tabs in sync.
+    window.addEventListener("storage", (event) => {
+      if (event.key !== STORAGE_KEY) return;
+      state.todos = load();
+      render();
+    });
+
+    render();
+  </script>
